import { useEffect, useState } from 'react';
import { useDispatch } from 'react-redux';

import { loadFilters, setCurrentPage } from 'redux/slices/filters';
import { AppDispatch } from 'redux/types';

import {
  WATCH_TOWER_MOCK_FILTERS,
  WATCH_TOWER_PAGE_NAME,
} from '../../constants';
import { watchTowerFilterPreset } from '../../data/watchTowerFilterPreset';

export function useWatchTowerFilterMock(): boolean {
  const dispatch = useDispatch<AppDispatch>();
  const [isReady, setIsReady] = useState(!WATCH_TOWER_MOCK_FILTERS);

  useEffect(() => {
    if (!WATCH_TOWER_MOCK_FILTERS) {
      return;
    }

    dispatch(setCurrentPage(WATCH_TOWER_PAGE_NAME));
    dispatch(
      loadFilters.pending('', {
        pageName: WATCH_TOWER_PAGE_NAME,
      }),
    );
    dispatch(
      loadFilters.fulfilled(
        {
          pageName: WATCH_TOWER_PAGE_NAME,
          dataFilters: watchTowerFilterPreset,
          rawData: watchTowerFilterPreset,
        },
        'watch-tower-filter-mock',
        { pageName: WATCH_TOWER_PAGE_NAME },
      ),
    );
    setIsReady(true);
  }, [dispatch]);

  return isReady;
}
